mapper.select:
SELECT att_id, emp_id, work_date, check_in, check_out, work_minutes, overtime_minutes, status, note
  FROM attendance
 WHERE emp_id = #{empId} AND work_date = #{workDate}

mapper.update:
UPDATE attendance
   SET check_out = #{checkOut},
       work_minutes = #{workMinutes},
       overtime_minutes = #{overtimeMinutes},
       status = #{status}
 WHERE att_id = #{attId}

mapper.select:
SELECT att_id, emp_id, work_date, check_in, check_out, work_minutes, overtime_minutes, status, note
  FROM attendance
 WHERE emp_id = #{empId}
   AND work_date BETWEEN #{start} AND #{end}
 ORDER BY work_date

SELECT e.emp_id AS emp_id, e.emp_name AS emp_name, d.dept_name AS dept_name, SUM(CASE WHEN a.check_in IS NOT NULL THEN 1 ELSE 0 END) AS working_days, SUM(CASE WHEN a.status = 'LATE' THEN 1 ELSE 0 END) AS late_count, COALESCE(SUM(a.overtime_minutes), 0) AS overtime_minutes, COALESCE(SUM(CASE WHEN a.status = 'LEAVE' THEN 1 WHEN a.status = 'HALF_LEAVE' THEN 0.5 ELSE 0 END), 0) AS leave_used_days FROM employee e JOIN department d ON d.dept_id = e.dept_id LEFT JOIN attendance a ON a.emp_id = e.emp_id AND a.work_date BETWEEN #{start} AND #{end} WHERE e.use_yn = 'Y' AND e.dept_id IN
#{deptId}
GROUP BY e.emp_id, e.emp_name, d.dept_name ORDER BY d.dept_name, e.emp_name
